const source = [1420, 1580, 1490, 1820, 1680, 1550, 1890, 2240, 2010, 2130, 1960, 2370, 2580, 2290, 2470, 2840, 2610, 2730, 2490, 2810, 3170, 2910, 3070, 3350, 3120, 3490, 3270, 3620, 3450, 3810];
