een;border-top:1px solid var(--border);padding:15px 25px;color:var(--muted);font-size:9px}.chart-footer>span{display:flex;align-items:center;gap:6px}.data-status{color:var(--secondary)}.data-status>span{height:5px;width:5px}.insight{display:flex;gap:13px;align-items:center;padding:18px 21px;background:var(--accent-soft);border:1px solid color-mix(in srgb,var(--accent) 11%,var(--border));border-radius:9px;margin-top:19px}.insight-icon{width:34px;height:34px;display:grid;place-items:center;background:var(--surface);color:var(--accent);border:1px solid color-mix(in srgb,var(--accent) 15%,var(--border));border-radius:9px}.insight strong{font-size:11px;font-weight:600}.insight p{font-size:10px;color:var(--secondary);margin:5px 0 0}.insight p b{font-weight:600;color:var(--accent)}.insight-tag{margin-left:auto;white-space:nowrap;color:var(--accent);font-size:9px;border:1px solid color-mix(in srgb,var(--accent) 20%,transparent);padding:6px 9px;border-radius:15px}.page-footer{padding:27px 0 25px;display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:9px}.page-footer>span:first-child{font-size:16px;font-weight:700;letter-spacing:-.5px}.footer-dot{color:var(--accent)}.footer-caption{margin-left:13px;font-size:9px;font-weight:400;letter-spacing:0}.footer-spark{color:var(--accent);font-size:17px;margin-left:5px;vertical-align:-2px}
