          <svg className="line-chart" viewBox="0 0 1120 330" role="img" aria-label={`Линейный график посещаемости за ${days} дней. Всего ${format(total)} посетителей. Используйте стрелки для просмотра значений.`} tabIndex={0} onMouseLeave={() => setActive(null)} onKeyDown={event => {
            if (event.key === '"'ArrowRight' || event.key === 'ArrowLeft') {event.preventDefault(); setActive(old => Math.max(0, Math.min(days - 1, (old ?? -1) + (event.key === 'ArrowRight' ? 1 : -1))));}
            if (event.key === 'Escape') setActive(null);
          }} onBlur={() => setActive(null)}>
            <defs><linearGradient id={gradientId} x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0%\" stopColor=\"var(--accent)\" stopOpacity=\".14\"/><stop offset=\"100%\" stopColor=\"var(--accent)\" stopOpacity=\".005\"/></linearGradient></defs>
            {[0, 1000, 2000, 3000, 4000, 5000].map(value => <g key={value}><line x1=\"60\" x2=\"1080\" y1={y(value)} y2={y(value)} stroke=\"var(--grid)\" strokeDasharray=\"3 5\"/><text x=\"42\" y={y(value) + 4} textAnchor=\"end\" className=\"axis-label\">{format(value)}</text></g>)}
            {visible && <path d={"'`${line} L 1080,282 L 60,282 Z`} fill={`url(#${gradientId})`}/>}
            {comparison && <path d={previousLine} fill="none" stroke="var(--previous-line)" strokeWidth="2" strokeDasharray="5 6" strokeLinecap="round"/>}
            {visible && <path d={line} fill="none" stroke="var(--accent)" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>}
            {Array.from({length: 7}, (_, i) => Math.round(i * (days - 1) / 6)).map(i => <text key={i} x={x(i)} y="316" textAnchor="middle" className="axis-label">{dateLabel(data[i].date)}</text>)}
            {active !== null && <g><line x1={x(active)} x2={x(active)} y1="28" y2="282" stroke="var(--previous-line)" strokeDasharray="4 4"/>{visible && <circle cx={x(active)} cy={y(data[active].value)} r="5" fill="var(--accent)" stroke="var(--surface)" strokeWidth="3"/>}{comparison && <circle cx={x(active)} cy={y(data[active].previous)} r="4" fill="var(--previous-line)" stroke="var(--surface)" strokeWidth="2"/>}</g>}
            {data.map((item, i) => <rect key={i} x={x(i) - 510 / (days - 1)} y="20" width={1020 / (days - 1)} height="270" fill="transparent" onMouseEnter={() => setActive(i)} onTouchStart={() => setActive(i)}><title>{dateLabel(item.date)}: {format(item.value)} посетителей</title></rect>)}
          </svg>
          {selected && active !== null && <div className="chart-tooltip" role="status" style={{left: `${Math.min(79, Math.max(9, x(active) / 1120 * 100))}%`}}><strong>{dateLabel(selected.date)} 2026</strong>{visible && <div><span><i/>Посетители</span><b>{format(selected.value)}</b></div>}{comparison && <div><span><i className="previous-dot"/>Прошлый период</span><b>{format(selected.previous)}</b></div>}</div>}
